mapper.select:
/*"getItemSeries"*/
SELECT ' 공급사' AGENT, -- [00] '품목코드' BUYER_ITEM_NO, -- [01] '단가' UNIT_PRICE, -- [02] '신청수량' REQ_CNT, -- [03] ATTB_NM1 AS A1, -- [04] ATTB_NM2 AS A2, -- [05] ATTB_NM3 AS A3, -- [06] ATTB_NM4 AS A4, -- [07] ATTB_NM5 AS A5, -- [08] '' DESCRIPTION, -- [09] '' SPECIFICATION, -- [10] '' CONTRACT_NO, -- [11] '' CONTRACT_SEQ, -- [12] '' CATEGORY_NO, -- [13] '' CATEGORY_TEXT, -- [14] '' AGENT_CODE, -- [15] '' BYIT_COMORG_CODE -- [16] FROM ITEMATTR WHERE 1=1
AND STDCATEG_ID = #{st_stdcateg_id}
UNION
SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT) AGENT, A.BUYER_ITEM_NO, TO_CHAR(a.UNIT_PRICE) UNIT_PRICE, '' REQ_CNT, B.ATTB_NM1 A1, B.ATTB_NM2 A2, B.ATTB_NM3 A3, B.ATTB_NM4 A4, B.ATTB_NM5 A5, A.DESCRIPTION, A.SPECIFICATION, A.CONTRACT_NO, A.CONTRACT_SEQ, C.CATEGORY_NO, C.CATEGORY_TEXT, A.AGENT AGENT_CODE, A.BUYER BYIT_COMORG_CODE FROM ICOMCQDT A, ITEMMAST B, ICOMBYIT C WHERE A.BUYER = #{st_byca_comorg_code}
AND A.STDCATLG_ID = #{st_stdcatlg_id}
AND A.STDCATLG_ID = B.STDCATLG_ID(+) AND A.ITEM_SEQ = B.ITEM_SEQ(+) AND A.BUYER = C.BUYER AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.STATUS <> 'D' AND B.STATUS(+) <> 'D' AND C.STATUS <> 'D' AND C.PRODUCT_CLOSE_FLAG = 'N' AND A.BELOW_COMORG_CODE = DECODE(A.BELOW_COMORG_CODE,'ABOVE','ABOVE', DECODE((SELECT COUNT(*) FROM ICOMCQDT WHERE STATUS <> 'D' AND BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO AND BELOW_COMORG_CODE = #{buyer} ) , 0, 'THE_OTHERS', #{buyer} ) )
ORDER BY 1
